            throw new IllegalArgumentException("Size must be non-negative: " + size);
        }
        final int initialCapacity = this.bytes.length;
        final int newCapacity = Math.max(initialCapacity + size, 16);

        // Prevent overflow
        if (newCapacity < 0) {
            throw new OutOfMemoryError("Required capacity exceeds maximum array size");
        }

        this.bytes = java.util.Arrays.copyOf(this.bytes, newCapacity);
