        if (!graph.isValid()) {
            throw new IllegalArgumentException("invalid graph");
        }

        // Check if the graph has at least one vertex
        int vertexCount = graph.degreeStream().count();
        if (vertexCount == 0) {
            throw new IllegalArgumentException("graph must have at least one vertex");
        }

        // Check if the graph is simple
        if (!graph.isSimple()) {
            throw new IllegalArgumentException("graph must be simple");
        }

        // Create a mapping from the graph to itself
        IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>() {
            @Override
            public G aimedForEdge(E e) {
