public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    if (actualTypeArguments.length == 0) {
        return null;
    }
    TypeVariable<?>[] typeVariables = parameterizedType.getRawType().getTypeParameters();
    if (typeVariables.length == 0) {
        return null;
    }
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    if (targetType instanceof ParameterizedType) {
        ParameterizedType targetParameterizedType = (ParameterizedType) targetType;
        TypeVariable<?>[] targetTypeVariables = targetParameterizedType.getRawType().getTypeParameters();
        Type[] targetActualTypeArguments = targetParameterizedType.getActualTypeArguments();
        for (int i = 0; i < targetTypeVariables.length && i < targetActualTypeArguments.length; i++) {
            typeVariableMap.put(targetTypeVariables[i], targetActualTypeArguments[i]);
        }
    } else if (targetType.isAssignableFrom((Class<?>) (parameterizedType.getRawType() instanceof Class ? parameterizedType.getRawType() : null))) {
        // No type variable information from targetType, cannot resolve
        return null;
    }
    Class<?>[] result = new Class[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArg = actualTypeArguments[i];
        if (typeArg instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArg;
            Type resolvedType = typeVariableMap.get(typeVariable);
            if (resolvedType instanceof Class) {
                result[i] = (Class<?>) resolvedType;
            } else {
                return null;
            }
        } else if (typeArg instanceof Class) {
            result[i] = (Class<?>) typeArg;
        } else {
            return null;
        }
    }
    return result;
}

