public static void createConfigurationDirectory() {
    try {
        File homeDir = new File(System.getProperty("user.home"));
        String osName = System.getProperty("os.name").toLowerCase();
        File configDir;

        if (osName.contains("win")) {
            // Check for "Documents and Settings" directory (Windows 2000)
            File docsAndSettingsDir = new File(homeDir, "Documents and Settings");
            if (docsAndSettingsDir.exists() && docsAndSettingsDir.isDirectory()) {
                configDir = new File(docsAndSettingsDir, "lf5");
            } else {
                // Fallback to user.home for modern Windows or if D&S doesn't exist
                configDir = new File(homeDir, "lf5");
            }
        } else {
            configDir = new File(homeDir, "lf5");
        }

        if (!configDir.exists()) {
            if (!configDir.mkdirs()) {
                throw new IOException("Failed to create configuration directory: " + configDir.getAbsolutePath());
            }
        }
    } catch (Exception e) {
        System.err.println("Error creating configuration directory: " + e.getMessage());
        // Depending on requirements, we might want to rethrow or log. Since the instruction says
        // "The method implementation must handle potential invalid inputs and runtime issues 
        // with exception-handling behavior", but for a "create directory" utility, failing 
        // silently or throwing a RuntimeException is common. I will throw a RuntimeException 
        // to indicate failure clearly, or just log. Let's stick to standard practice: 
        // if the directory creation fails, it's a critical error for the application state.
        throw new RuntimeException("Could not create configuration directory", e);
    }
}

