static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Time bucket must be a positive long value.");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be a positive integer.");
    }

    // Extract year, month, day from the time bucket (YYYYMMDD format)
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Create a calendar for the date
    java.util.Calendar cal = java.util.GregorianCalendar.getInstance();
    cal.clear();
    cal.set(year, month - 1, day);

    // Determine the start of the time bucket period
    // We need to find the last day in the sequence: 1, 1- dayStep, 1+dayStep,...
    // Essentially, we're grouping days into buckets of size dayStep, starting from day 1
    // bucket start day = ((day - 1) / dayStep) * dayStep + 1

    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    int bucketEndDay = bucketStartDay + dayStep - 1;

    // Adjust if the bucket ends after the last day of the month
    int daysInMonth = cal.getActualMaximum(java.util.Calendar.DAY_OF_MONTH);
    if (bucketEndDay > daysInMonth) {
        bucketEndDay = daysInMonth;
    }

    // Now check if the given day falls in the first bucket (day <= dayStep) -> return day 1
    // For subsequent buckets, return the last day of the bucket
    // Example: dayStep=11, 20000105: day=5, bucket 1 (days 1-11), return 1
    // 20000115: day=15, bucket 2 (days 12-22 but month has 31 days so 12-22), return 22? 
    // Wait, the problem says 20000115 re-formatted is 20000112. 
    // Let me reconsider. 
    // 20000115 with dayStep 11 -> 20000112
    // So it seems like for each bucket, we return the start of the bucket? No, 20000105 -> 20000101 (start), 20000115 -> 20000112 (start of that bucket would be 12), 20000123 -> 20000123 
    // Day 15: (15-1)/11 = 1, 1*11+1 = 12. So bucket start is 12. Return 12 -> 20000112. Yes.
    // Day 23: (23-1)/11 = 2, 2*11+1 = 23. Bucket start is 23. Return 23 -> 20000123. Yes.
    // Day 5: (5-1)/11 = 0, 0*11+1 = 1. Bucket start is 1. Return 1 -> 20000101. Yes.

    // So the re-formatted bucket day is the start of the bucket, which is ((day-1)/dayStep)*dayStep + 1
    // But wait, for 20000123, that gives 23. That matches.

    // But hold on, what if the bucket start exceeds daysInMonth? That shouldn't happen since day <= daysInMonth.

    // So simply:
    int reformattedDay = ((day - 1) / dayStep) * dayStep + 1;

    // But we must also check: what if the computed reformattedDay exceeds daysInMonth? 
    // Since day is valid (1..daysInMonth), (day-1)/dayStep is finite, and reformattedDay <= day <= daysInMonth, so it's fine.

    long result = (long) timeBucket - day + reformattedDay;

    return result;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int charIndex = index;
    int endIndex = index + len;

    while (charIndex < endIndex && charIndex < str.length()) {
        char c = str.charAt(charIndex);

        // Check for surrogate pair
        if (Character.isHighSurrogate(c) && charIndex + 1 < endIndex && 
            Character.isLowSurrogate(str.charAt(charIndex + 1))) {
            // Supplemental character - 4 bytes in UTF-8
            size += 4;
            charIndex += 2;
        } else if (c >= 0x800) {
            // Non-BMP character but not a valid surrogate pair, or just a normal char
            if (Character.isSurrogate(c)) {
                // Isolated surrogate - encode as 3 bytes (replacement or according to spec)
                size += 3;
                charIndex += 1;
            } else {
                // 1-2 bytes would be for chars < 0x800, 3 bytes for 0x800-0xFFFF
                size += 3;
                charIndex += 1;
            }
        } else if (c >= 0x80) {
            // 2 bytes in UTF-8
            size += 2;
            charIndex += 1;
        } else {
            // ASCII character - 1 byte
            size += 1;
            charIndex += 1;
        }
    }

