public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative: " + byteLength + " < 0");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset " + byteOffset + " and byteLength " + byteLength 
                + " are out of range for byte array of length " + byteArrayValue.length);
        }
    } else if (byteOffset != 0 || byteLength != 0) {
        throw new IllegalArgumentException("byteOffset and byteLength must be 0 when byteArrayValue is null");
    }
    if (this.size + byteLength > Integer.MAX_VALUE) {
        throw new OutOfMemoryError("byte vector too large");
    }
    this.ensureCapacity(this.size + byteLength);
    if (byteArrayValue != null && byteLength > 0) {
        System.arraycopy(byteArrayValue, byteOffset, this.values, this.size, byteLength);
    } else if (byteLength > 0) {
        // Fill with zeros (nullbytes)
        Arrays.fill(this.values, this.size, this.size + byteLength, (byte)0);
    }
    this.size += byteLength;
    return this;
}

