public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final int length = str.length();
    int offset = 0;
    while (offset < length) {
        final char ch = str.charAt(offset);
        if (ch < 0x80) {
            offset++;
            continue;
        } else if (ch < 0x800) {
            lb.writeByte((byte) (0xc0 | (ch >>> 6)));
            lb.writeBytes((byte) (0x80 | (ch & 0x3f)));
            offset++;
            continue;
        } else if (!Character.isSurrogate(ch)) {
            lb.writeByte((byte) (0xe0 | (ch >>> 12)));
            lb.writeBytes((byte) (0x80 | ((ch >>> 6) & 0x3f)));
            lb.writeBytes((byte) (0x80 | (ch & 0x3f)));
            offset++;
            continue;
        } else if (Character.isLowSurrogate(ch)) {
            throw new IllegalArgumentException();
        }
        // The character to encode is a high-surrogate code-point.
        final char hiSurrogate = ch;
        if (length == (offset + 1)) {
            throw new IllegalArgumentException();
        }
        final char loSurrogate = session.charAt(str, offset + 1);
        if (!Character.isLowSurrogate(loSurrogate)) {
            throw new IllegalArgumentException();
        }
        final int codePoint = ((hiSurrogate - 0xd800) << 10) + loSurrogate - 0xdc00 + 0x10000;
        lb.writeByte((byte) (0xf0 | (codePoint >>> 18)));
        lb.writeBytes((byte) (0x80 | ((codePoint >>> 12) & 0x3f)));
        lb.writeBytes((byte) (0x80 | ((codePoint >>> 6) & 0x3f)));
        lb.writeBytes((byte) (0x80 | (codePoint & 0x3f)));
        offset += 2;
    }
    return lb;
}

