public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution: replace ${...} patterns with values from props
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (i < value.length() - 2 && value.charAt(i) == '$' && value.charAt(i + 1) == '{' && value.charAt(i + 2) == '}') {
            // Edge case: ${} with no content, skip
            i += 3;
        } else if (i < value.length() - 1 && value.charAt(i) == '$' && value.charAt(i + 1) == '{') {
            int end = value.indexOf('}', i + 2);
            if (end != -1) {
                String innerKey = value.substring(i + 2, end);
                String innerValue = props.getProperty(innerKey);
                if (innerValue != null) {
                    // Recursively substitute
                    sb.append(findAndSubst(innerKey, props));
                } else {
                    sb.append(value.substring(i, end + 1));
                }
                i = end + 1;
            } else {
                sb.append(value.charAt(i));
                i++;
            }
        } else {
            sb.append(value.charAt(i));
            i++;
        }
    }
    // Handle regex meta-characters and escape sequences
    for (int j = 0; j < sb.length(); j++) {
        char c = sb.charAt(j);
        if (c == '\n') {
            sb.setCharAt(j, ' ');
        }
        if (c == '\t') {
            sb.setCharAt(j, ' ');
        }
    }
    String result = sb.toString();
    if (result.contains("=")) {
        String[] parts = result.split("=", -1);
        result = (parts.length > 1) ? parts[1] : "";
    }
    // If the result contains regex characters, escape them
    return result.replace("$", "\\$").replace("\\", "\\\\").replace("{", "\\{").replace("}", "\\}").replace("^", "\\^").replace(".*", ".*").replace("[", "\\[").replace("]", "\\]").replace("*", "\\*").replace("+", "\\+").replace("?", "\\?").replace("|", "\\|").replace("(", "\\(").replace(")", "\\)");
}

