public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
    List<PathSegmentImpl> segments = new ArrayList<PathSegmentImpl>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    boolean decoded = decode;
    if (path.startsWith("/")) {
        path = path.substring(1);
        if (path.equals("")) {
            return segments;
        }
    }
    int start = 0;
    int len = path.length();
    for (int i = 0; i < len; i++) {
        char c = path.charAt(i);
        if (c == '/') {
            String segment = path.substring(start, i);
            if (segment.length() > 0) {
                segments.add(new PathSegmentImpl(segment, decoded, decoded));
            }
            start = i + 1;
        }
    }
    if (start < len) {
        String segment = path.substring(start, len);
        if (segment.length() > 0) {
            segments.add(new PathSegmentImpl(segment, decoded, decoded));
        }
    }
    return segments;
}

