public Converter lookup(final Class<?> clazz) {
        if (clazz == null) {
            throw new IllegalArgumentException("Class must not be null");
        }

        // First check for a direct converter specific to this class
        Converter converter = this.converters.get(clazz);
        if (converter != null) {
            return converter;
        }

        // If not found, check the hierarchy of interfaces and superclasses
        Class<?> classToCheck = clazz;
        while (classToCheck != null) {
            // Check if the class itself or any of its interfaces have a registered converter
            for (Class<?> iface : classToCheck.getInterfaces()) {
                converter = this.converters.get(iface);
                if (converter != null) {
                    return converter;
                }
            }

            // Move up the class hierarchy
            classToCheck = classToCheck.getSuperclass();
        }

        return null;
    }

public long readRawVarint64() throws IOException {
        long result = 0;
        int shift = 0;
        while (shift < 64) {
            byte b = readByte();
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
        }
        if (shift >= 64) {
            throw new IOException("varint too long");
        }
        return result;
    }

