private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    if (descriptor.charAt(0) == 'L') {
        // Class type: pop one frame
        this.frameStack.pop();
    } else if (descriptor.charAt(0) == '[') {
        // Array type: pop one frame
        this.frameStack.pop();
    } else if (descriptor.charAt(0) == '(') {
        // Method descriptor: parse and pop argument types
        int closingParen = descriptor.lastIndexOf(')');
        if (closingParen < 1) {
            return;
        }
        String args = descriptor.substring(1, closingParen);
        parseAndPopArgs(args);
    } else {
        // Primitive type: pop one frame
        this.frameStack.pop();
    }
}

