public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int contentSize = 0;
    LinkedBuffer lastNode = node;
    while (lastNode.next != null) {
        lastNode = lastNode.next;
    }
    // Write from head to tail
    LinkedBuffer current = node;
    while (current != null) {
        contentSize += current.contentLength();
        out.write(current.content, 0, current.contentLength());
        if (current.next != null) {
            // Write separator length
            if (current.next.contentLength() > 0) {
                out.writeInt(current.next.contentLength());
                contentSize += 4;
            }
        }
        current = current.next;
    }
    return contentSize;
}

