private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> contentMap = new HashMap<>();
    if (jsonObject != null) {
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement element = entry.getValue();
            if (element != null) {
                if (element.isJsonPrimitive()) {
                    JsonPrimitive primitive = element.getAsJsonPrimitive();
                    if (primitive.isBoolean()) {
                        contentMap.put(key, primitive.getAsBoolean());
                    } else if (primitive.isNumber()) {
                        contentMap.put(key, primitive.getAsNumber());
                    } else {
                        contentMap.put(key, primitive.getAsString());
                    }
                } else if (element.isJsonArray()) {
                    List<Object> list = new ArrayList<>();
                    for (JsonElement elem : element.getAsJsonArray()) {
                        if (elem != null) {
                            if (elem.isJsonPrimitive()) {
                                JsonPrimitive prim = elem.getAsJsonPrimitive();
                                if (prim.isBoolean()) {
                                    list.add(prim.getAsBoolean());
                                } else if (prim.isNumber()) {
                                    list.add(prim.getAsNumber());
                                } else {
                                    list.add(prim.getAsString());
                                }
                            } else if (elem.isJsonObject()) {
                                list.add(buildContent(elem.getAsJsonObject()));
                            }
                        } else {
                            list.add(null);
                        }
                    }
                    contentMap.put(key, list);
                } else if (element.isJsonObject()) {
                    contentMap.put(key, buildContent(element.getAsJsonObject()));
                } else if (element.isJsonNull()) {
                    contentMap.put(key, null);
                }
            } else {
                contentMap.put(key, null);
            }
        }
    }
    return contentMap;
}

