public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    StringBuilder builder = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Trailing backslash in string");
            }
            i++;
            char next = str.charAt(i);
            switch (next) {
                case 'n':
                    builder.append('\n');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case 'b':
                    builder.append('\b');
                    break;
                case '\'':
                    builder.append('\'');
                    break;
                case '"':
                    builder.append('"');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= len) {
                        throw new Exception("Invalid unicode escape sequence: missing digits");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        builder.append((char) codePoint);
                        i += 4;
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence: " + hex);
                    }
                    break;
                default:
                    // For unknown escapes, keep the backslash and the character
                    builder.append('\\');
                    builder.append(next);
                    break;
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

private static String javaCharset(String charset) {
    if (charset == null || charset.trim().isEmpty()) {
        return "ISO-8859-1"; // Default Java charset or throw exception
    }

    String upper = charset.toUpperCase().trim();
    switch (upper) {
        case "US-ASCII":
        case "ASCII":
            return "US-ASCII";
        case "ISO-8859-1":
        case "LATIN1":
        case "L1":
        case "ISO-8859-1:1987":
            return "ISO-8859-1";
        case "UTF-8":
        case "UTF8":
        case "UTF-8:2003":
            return "UTF-8";
        case "UTF-16":
        case "UNICODE":
        case "UTF-16BE":
            return "UTF-16BE";
        case "UTF-16LE":
            return "UTF-16LE";
        case "UTF-16:2003":
            return "UTF-16";
        default:
            // Try to return the input as-is if it seems valid, otherwise default
            if (charset.length() > 0) {
                return charset;
            }
            return "ISO-8859-1";
    }
}

