private int computeBinaryLog(int n) {
        if (n <= 0) {
            return 0;
        }
        int result = 0;
        int value = n;
        while (value > 0) {
            value >>= 1;
            result++;
        }
        return result;
    }

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Sets must not be null");
    }

    Set<V> result;
    // Choose the smaller set to iterate over for efficiency
    if (set1.size() <= set2.size()) {
        result = new HashSet<>(set1);
        result.retainAll(set2);
    } else {
        result = new HashSet<>(set2);
        result.retainAll(set1);
    }

    return result;
}

