private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.trim().isEmpty()) {
        throw new IllegalArgumentException("Model name cannot be null or empty for sharding key validation");
    }

    // Check if the model's sharding key indices are continuous
    List<Integer> indices = getShardingKeyIndices(modelName);
    indices.sort(Integer::compareTo);

    for (int i = 1; i < indices.size(); i++) {
        if (indices.get(i) != indices.get(i - 1) + 1) {
            throw new IllegalStateException(
                String.format("Sharding key indices for model '%s' are not continuous. Found indices: %s", 
                    modelName, indices)
            );
        }
    }
}

