public boolean containsKey(final Object key) {
        if (key == null) {
            return false;
        }
        int hash = hash(key);
        Node<K, V>[] table = this.table;
        int n = table.length;
        int index = hash & (n - 1);
        Node<K, V> e = table[index];
        if (e == null) {
            return false;
        }
        if (key.equals(e.key)) {
            return true;
        }
        while ((e = e.next) != null) {
            if (key.equals(e.key)) {
                return true;
            }
        }
        return false;
    }

