protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null) {
        throw new IllegalArgumentException("Tour set cannot be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    // If the tour is empty, return an empty path
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, null, null, null, 0, new HashSet<>());
    }

    // Find the start vertex of the tour
    V start = null;
    V current = null;
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // Create a map from edge to adjacent vertices for quick lookup
    Map<E, NetworkBean> edgeBeanMap = new HashMap<>();
    for (E edge : tour) {
        NetworkBean bean = graph.getEdgeBeans().get(edge);
        if (bean == null) {
            throw new IllegalArgumentException("Edge " + edge + " is not in the graph");
        }
        edgeBeanMap.put(edge, bean);
    }

    // Find a vertex that appears in only one edge (an endpoint of the path)
    Map<V, Integer> degreeMap = new HashMap<>();
    for (E edge : tour) {
        NetworkBean bean = edgeBeanMap.get(edge);
        V v1 = bean.getv1();
        V v2 = bean.getv2();
        degreeMap.put(v1, degreeMap.getOrDefault(v1, 0) + 1);
        degreeMap.put(v2, degreeMap.getOrDefault(v2, 0) + 1);
    }

    // Find start vertex (degree 1)
    for (Map.Entry<V, Integer> entry : degreeMap.entrySet()) {
        if (entry.getValue() == 1) {
            start = entry.getKey();
            break;
        }
    }

    // If no vertex has degree 1, it's a circuit, pick any vertex as start
    if (start == null) {
        if (graph.getVertices().isEmpty()) {
            return new DefaultGraphPath<>(graph, null, null, null, 0, new HashSet<>());
        }
        // Find a vertex that is in the tour
        for (E edge : tour) {
            NetworkBean bean = edgeBeanMap.get(edge);
            if (graph.containsVertex(bean.getv1())) {
                start = bean.getv1();
                break;
            }
        }
        if (start == null) {
            throw new IllegalArgumentException("Unable to find start vertex for tour");
        }
    }

    current = start;
    vertices.add(current);
    Set<V> visitedVertices = new HashSet<>();
    visitedVertices.add(current);
    Set<E> usedEdges = new HashSet<>();

    // Traverse the tour
    while (usedEdges.size() < tour.size()) {
        // Find an unused edge incident to current vertex
        E nextEdge = null;
        V nextVertex = null;
        for (E edge : tour) {
            if (usedEdges.contains(edge)) {
                continue;
            }
            NetworkBean bean = edgeBeanMap.get(edge);
            V v1 = bean.getv1();
            V v2 = bean.getv2();
            if (v1.equals(current)) {
                nextEdge = edge;
                nextVertex = v2;
                break;
            } else if (v2.equals(current)) {
                nextEdge = edge;
                nextVertex = v1;
                break;
            }
        }

        if (nextEdge == null) {
            // No more edges to traverse
            break;
        }

        if (!graph.getEdgeBean(nextEdge).getv1().equals(current) && 
            !graph.getEdgeBean(nextEdge).getv2().equals(current)) {
            throw new IllegalArgumentException("Invalid tour: edge " + nextEdge + " is not incident to vertex " + current);
        }

        current = nextVertex;
        vertices.add(current);
        edges.add(nextEdge);
        usedEdges.add(nextEdge);

        if (!visitedVertices.add(current)) {
            // If we've already visited this vertex, it might be a circuit
            // Continue until all edges are used
        }
    }

    // Calculate total cost
    double totalCost = 0.0;
    for (E edge : edges) {
        totalCost += graph.getEdgeCost(edge);
    }

    V end = vertices.isEmpty() ? null : vertices.get(vertices.size() - 1);

    return new DefaultGraphPath<>(graph, start, end, edges, totalCost, tour);
}

