private String unescapeId(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < input.length()) {
            char c = input.charAt(i);
            if (c == '\\' && i + 1 < input.length()) {
                char next = input.charAt(i + 1);
                switch (next) {
                    case 'n':
                        result.append('\n');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case '\\':
                        result.append('\\');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    default:
                        result.append('\\');
                        result.append(next);
                        break;
                }
                i += 2;
            } else if (c == '"' && i == 0 && input.length() > 1 && input.charAt(input.length() - 1) == '"') {
                // If the string is quoted, handle it specially
                result.append(input.substring(1, input.length() - 1));
                i = input.length();
            } else {
                result.append(c);
                i++;
            }
        }
        return result.toString();
    }

