    if (dataset == null) {
        return false;
    }

    // Check if the dataset has the same number of columns as this bucket
    if (dataset.getNumberOfColumns() != getColumnCount()) {
        return false;
    }

    // Check if each column in the dataset is compatible with the corresponding column in this bucket
    for (int i = 0; i < getColumnCount(); i++) {
