        if (bounds.get(i) != null) {
            currentSum += bounds.get(i);
        }
        result.add((int) currentSum);
    }

    // Reverse to get correct ordering: result[i] corresponds to suffix starting at i
    Collections.reverse(result);

    return new Pair<>(result, totalSum);
}

