public static String base64Decode(final String s) {
    // Null check
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    // Try to decode using Base64 decoder
    try {
        byte[] decodedBytes = java.util.Base64.getDecoder().decode(s.trim());
        return new String(decodedBytes, java.nio.charset.StandardCharsets.UTF_8);
    } catch (IllegalArgumentException e) {
        // If standard decoding fails, try with MIME decoder (allows newlines)
        try {
            byte[] decodedBytes = java.util.Base64.getMimeDecoder().decode(s.trim());
            return new String(decodedBytes, java.nio.charset.StandardCharsets.UTF_8);
        } catch (IllegalArgumentException e2) {
            throw new IllegalArgumentException("Invalid Base64 string: " + s, e2);
        }
    }
}

