private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
        List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();

        // Get all edges in the graph
        for (E edge : graph.edgeSet()) {
            // Get endpoints of the edge
            int u = graph.getEdgeSource(edge);
            int v = graph.getEdgeTarget(edge);

            // Get the neighborhood of this edge (vertices adjacent to u and v)
            Set<Integer> neighborhood = new HashSet<>();
            for (int w : graph.adjacentVertices(u)) {
                neighborhood.add(w);
            }
            for (int w : graph.adjacentVertices(v)) {
                neighborhood.add(w);
            }
            // Find minimal separators in the neighborhood
            List<List<Pair<Integer,Integer>>> minimalSeparators = new ArrayList<>();

            // For each subset of neighborhood, check if it forms a separator
            // That separates u and v
            // We need to find minimal separators
            List<Integer> neighbors = new ArrayList<>(neighborhood);
            int n = neighbors.size();

            // Try all subsets of neighborhood
            for (int i = 0; i < (1 << n); i++) {
                List<Integer> subset = new ArrayList<>();
                for (int j = 0; j < n; j++) {
                    if ((i & (1 << j)) != 0) {
                        subset.add(neighbors.get(j));
                    }
                }

                // Check if subset is a separator for u and v
                // A separator is a set of vertices whose removal disconnects u and v
                // We can check this by doing BFS/DFS from u avoiding subset and seeing if v is reachable

                Set<Integer> separatorSet = new HashSet<>(subset);
                separatorSet.add(u); // We should not allow going through u in the BFS? Actually we start from u

                // BFS from u
                Set<Integer> visited = new HashSet<>();
                Queue<Integer> queue = new LinkedList<>();
                queue.offer(u);
                visited.add(u);
                boolean foundV = false;

                while (!queue.isEmpty() && !foundV) {
                    int current = queue.poll();
                    for (int neighbor : graph.adjacentVertices(current)) {
                        if (neighbor == v) {
                            foundV = true;
                            break;
                        }
                        if (!visited.contains(neighbor) && !separatorSet.contains(neighbor)) {
                            visited.add(neighbor);
                            queue.offer(neighbor);
                        }
                    }
                }

                // If v is not reachable from u (avoiding the separator), then separatorSet separates u from v
                if (!foundV) {
                    // Check if this separator is minimal
                    boolean minimal = true;
                    for (int j = 0; j < subset.size(); j++) {
                        List<Integer> smallerSubset = new ArrayList<>(subset);
                        smallerSubset.remove(j);

                        // Check if smallerSubset is also a separator
                        if (smallerSubset.isEmpty()) {
                            // If smallerSubset is empty, check if u and v are directly connected
                            boolean directlyConnected = graph.containsEdge(u, v);
                            if (directlyConnected) {
                                minimal = false;
                                break;
                            } else {
                                // If empty smaller subset separates u and v, then current subset is not minimal
                                minimal = false;
                                break;
                            }
                        } else {
                            // Check if smallerSubset is a separator
                            Set<Integer> smallerSet = new HashSet<>(smallerSubset);
                            visited.clear();
                            queue.clear();
                            queue.offer(u);
                            visited.add(u);
                            foundV = false;

                            while (!queue.isEmpty() && !foundV) {
                                int current = queue.poll();
                                for (int neighbor : graph.adjacentVertices(current)) {
                                    if (neighbor == v) {
                                        foundV = true;
                                        break;
                                    }
                                    if (!visited.contains(neighbor) && !smallerSet.contains(neighbor)) {
                                        visited.add(neighbor);
                                        queue.offer(neighbor);
                                    }
                                }
                            }

                            if (!foundV) {
                                minimal = false;
                                break;
                            }
                        }
                    }

                    if (minimal) {
                        // Convert subset to list of pairs
                        List<Pair<Integer,Integer>> separatorPairs = new ArrayList<>();
                        for (int vertex : subset) {
                            // The pair is the vertex with itself or a representation we need
                            separatorPairs.add(new Pair<>(vertex, vertex));
                        }
                        minimalSeparators.add(separatorPairs);
                    }
                }
            }

            // For each minimal separator, create a pair with the edge
            for (List<Pair<Integer,Integer>> separator : minimalSeparators) {
                result.add(new Pair<>(separator, edge));
            }
        }

        return result;
    }

