public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= this.length()) {
        throw new IllegalArgumentException("nameStart out of bounds: " + nameStart);
    }

    // Find the start of the next word or end of string
    int end = nameStart + 1;
    while (end < this.length() && !Character.isWhitespace(this.charAt(end))) {
        end++;
    }

    // If the word length is greater than 2, abbreviate; else, keep as is
    int wordLength = end - nameStart;
    if (wordLength > 4) {
        buf.append(this, nameStart, nameStart + 2);
        buf.append("...");
    } else {
        buf.append(this, nameStart, end);
    }
}

