private static <V,E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V u : vertices) {
        for (V v : vertices) {
            if (u.equals(v)) {
                continue;
            }
            if (!graph.containsEdge(u, v)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        return new ArrayList<>();
    }

    // Assuming leftBounds is a field that provides lower bound estimates for each key
    // The method will compute maxLowerBound as the maximum of these estimates across all keys
    List<Integer> lowerBounds = new ArrayList<>();
    int maxLowerBound = 0;
    for (K key : keys) {
        Integer bound = leftBounds.get(key);
        if (bound != null && bound > maxLowerBound) {
            maxLowerBound = bound;
        }
    }
    lowerBounds.add(maxLowerBound);
    return lowerBounds;
}

private void pop(final String descriptor) {
    int count = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B': case 'C': case 'I': case 'S': case 'Z':
                count++;
                break;
            case 'D': case 'J':
                count += 2;
                break;
            case 'L':
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    return;
                }
                count++;
                i = semicolon - 1;
                break;
            case '[':
                count++;
                break;
            case '(':
                i = descriptor.indexOf(')', i) - 1;
                break;
            case ')':
                return;
            default:
                return;
        }
    }

    for (int i = 0; i < count; i++) {
        outputFrameStack.pop();
    }
}

