private List<Integer> computeUpperBounds(List<K> keys) {
        List<Integer> upperBounds = new ArrayList<>();

        // Initialize the first upper bound with the first key
        if (!keys.isEmpty()) {
            upperBounds.add(1);

            // For each subsequent key, calculate an upper bound based on the difference from the previous key
            for (int i = 1; i < keys.size(); i++) {
                K currentKey = keys.get(i);
                K previousKey = keys.get(i - 1);

                // Calculate the difference between current and previous keys
                // Since we're working with integers, we can compute the absolute difference
                // As a simple heuristic for upper bound, use the difference + 1
                int diff = 0;
                try {
                    int currentValue = (Integer) currentKey;
                    int previousValue = (Integer) previousKey;
                    diff = currentValue - previousValue;
                } catch (ClassCastException e) {
                    // If keys are not integers, use a default increment
                    diff = 1;
                }

                int upperBound = Math.abs(diff) + 1;
                upperBounds.add(upperBound);
            }
        }

        return upperBounds;
    }

