public static String applyRelativePath(String path, String relativePath) {
        if (path == null) {
            return relativePath != null ? relativePath : "";
        }
        if (relativePath == null || relativePath.isEmpty()) {
            return path;
        }

        // Ensure path and relativePath use forward slashes
        path = path.replace('\\', '/');
        relativePath = relativePath.replace('\\', '/');

        // If the relative path is absolute, it overrides the original path
        if (relativePath.startsWith("/")) {
            return relativePath;
        }

        // Split path into segments
        String[] pathParts = path.split("/");
        List<String> pathSegments = new ArrayList<>();
        for (String part : pathParts) {
            if (!part.isEmpty()) {
                pathSegments.add(part);
            }
        }

        // Apply relative path segments
        String[] relativeParts = relativePath.split("/");
        for (String relativePart : relativeParts) {
            if (relativePart.isEmpty()) {
                continue;
            }
            if (".".equals(relativePart)) {
                continue;
            } else if ("..".equals(relativePart)) {
                if (!pathSegments.isEmpty()) {
                    pathSegments.remove(pathSegments.size() - 1);
                }
            } else {
                pathSegments.add(relativePart);
            }
        }

        // Reconstruct the full path
        StringBuilder result = new StringBuilder();
        if (path.startsWith("/")) {
            result.append('/');
        }
        for (int i = 0; i < pathSegments.size(); i++) {
            if (i > 0) {
                result.append('/');
            }
            result.append(pathSegments.get(i));
        }

        String finalPath = result.toString();
        // If path was not absolute and segments are empty, return "."
        if (pathSegments.isEmpty() && !path.startsWith("/")) {
            return ".";
        }
        return finalPath;
    }

