static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return new String[0];
    }

    int nonNullCount = 0;
    for (Object element : array) {
        if (element != null) {
            nonNullCount++;
        }
    }

    if (nonNullCount == array.length) {
        // All elements are non-null, try to return as-is if all are Strings
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // Not all elements are Strings, fall through
        }
    }

    String[] result = new String[nonNullCount];
    int index = 0;
    for (Object element : array) {
        if (element != null) {
            if (element instanceof String) {
                result[index++] = (String) element;
            } else {
                result[index++] = element.toString();
            }
        }
    }

    return result;
}

