private void checkIfPackedField() throws IOException {
        if (fieldNum == packedFieldNumber) {
            // Ask for packed fields for the next tag
            if (reader.isPackedField(fieldNum)) {
                // If we're reading a packed field, we need to read all the values in the field
                if (reader.getFieldDescriptor().getType() != Type.MESSAGE) {
                    // If this is a repeated scalar field, read all the values
                    while (reader.hasNext()) {
                        onValue((T) reader.getValue());
                    }
                }
            } else {
                // It's a normal length-delimited field, read the next tag
                reader.nextTag();
            }
        }
    }

