private String buildContentRange() {
        if (servletResponse == null) {
            return null;
        }
        if (targetContentType == null) {
            return null;
        }
        if (outputLength == -1) {
            return null;
        }
        if (outputLength == 0) {
            return "bytes */" + outputLength;
        }
        long rangeStart = outputLength - 1;
        long rangeEnd = outputLength - 1;
        long totalLength = outputLength;
        if (rangeStart >= totalLength) {
            rangeStart = totalLength - 1;
            rangeEnd = totalLength - 1;
        }
        return "bytes " + rangeStart + "-" + rangeEnd + "/" + totalLength;
    }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        if (file == null) {
            throw new IOException("Input file is null");
        }
        if (!file.exists()) {
            throw new IOException("Input file does not exist: " + file.getAbsolutePath());
        }
        if (!file.canRead()) {
            throw new IOException("Input file is not readable: " + file.getAbsolutePath());
        }
        if (timeRanges == null) {
            throw new IOException("Time ranges list is null");
        }

        List<ThreadSnapshot> snapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }

                try {
                    ThreadSnapshot snapshot = parseLine(line);
                    if (snapshot != null) {
                        if (matchesAnyTimeRange(snapshot, timeRanges)) {
                            snapshots.add(snapshot);
                        }
                    }
                } catch (IllegalArgumentException e) {
                    // Skip lines that cannot be parsed
                    continue;
                }
            }
        }
        return snapshots;
    }
